/** Isolated panel POC fake. The test decides when a reconnect has advertised modern panels. */
panelProbeCalls: Array<{ mode: PanelProbeMode; value?: number }> = []
panelProbeEnabled = false
panelProbeAdvertised = false
panelProbeBaselineSent = false
panelProbeLast: Pick<PanelProbeStatus, 'state' | 'mode' | 'value' | 'detail'> | null = null
async panelProbe(mode: PanelProbeMode, value?: number): Promise<PanelProbeStatus> {
  this.panelProbeCalls.push({ mode, value })
  if (mode === 'enable' || mode === 'disable') {
    this.panelProbeEnabled = mode === 'enable'
    this.panelProbeAdvertised = false
    this.panelProbeBaselineSent = false
    this.panelProbeLast = null
  }
  const ready = this.panelProbeEnabled && this.panelProbeAdvertised
  const sent = ready && ['baseline', 'zoom', 'physical', 'apply'].includes(mode) && (mode === 'baseline' || this.panelProbeBaselineSent)
  if (mode === 'baseline' && sent) this.panelProbeBaselineSent = true
  if (['baseline', 'zoom', 'physical', 'apply'].includes(mode)) {
    this.panelProbeLast = {
      state: sent ? 'LOCAL_SENT' : 'REJECTED', mode, value,
      detail: sent ? 'Encrypted AirPlay event written. No iOS acknowledgement or visual effect proven.'
        : 'No live panel event sent.',
    }
  }
  return {
    enabled: this.panelProbeEnabled, advertised: ready,
    baselineSent: this.panelProbeBaselineSent,
    state: this.panelProbeLast?.state ?? (!this.panelProbeEnabled ? 'OFF' : ready ? 'DESCRIPTOR_OFFERED' : 'RECONNECT_REQUIRED'),
    detail: this.panelProbeLast?.detail,
    ack: 'NOT_OBSERVED', visualEffect: 'UNKNOWN',
    mode: this.panelProbeLast?.mode, value: this.panelProbeLast?.value,
  }
}

