async function runPanel(mode: 'enable' | 'disable' | 'baseline') {
  setPanelBusy(true)
  setPanelResult(null)
  try {
    const status = await backend.panelProbe(mode)
    setPanelStatus(status)
    if (mode === 'baseline') {
      setPanelResult(status.state === 'LOCAL_SENT'
        ? 'Baseline sent to event socket. Keep the same session and change Zoom factor below.'
        : 'Baseline not sent: ' + (status.detail ?? status.state))
    } else {
      setPanelResult(mode === 'enable'
        ? 'Live test enabled. Reconnect CarPlay once, then send the unchanged baseline.'
        : 'Live test disabled. Reconnect to return to the normal display descriptor.')
    }
  } catch (error) { setPanelResult('Panel probe error: ' + String(error)) }
  finally { setPanelBusy(false) }
